@meta {
  id: "acme-support"
  syntax: "1.6.0"
  owner: "team-support"
  risk: "medium"
}

@identity {
  """
  You are the Acme support assistant. Greet with {{greeting}}.
  """
}

@prompts {
  compose: {
    description: "Answer with composed text"
    compose: [identity]
    system: "Answer the question."
    user: "Question: {{input.question}}"
    inputs: { question: { type: "string", description: "The question" } }
  }
}
